function discussionResponsesMarkup(d,responses){
 const messages=responses.map((reply,i)=>({...reply,id:reply.id||`legacy-${i}`,parentId:reply.parentId||'original',time:reply.time||'RECENTLY'}));
 const byId=new Map(messages.map(reply=>[reply.id,reply]));
 const visited=new Set();
 function branch(parentId,depth){return messages.filter(reply=>reply.parentId===parentId&&!visited.has(reply.id)).map(reply=>{
  visited.add(reply.id);
  const parentName=parentId==='original'?d.author:byId.get(parentId)?.author||d.author;
  const entry=`<article class="forum-response ${depth?'is-nested':'is-root'}" style="--reply-depth:${Math.min(depth,2)}" id="response-${esc(reply.id)}"><span class="forum-response-avatar" aria-hidden="true">${esc(publisherInitials(reply.author))}</span><div class="forum-response-content"><div class="forum-response-by"><button class="profile-author-link" type="button" data-public-author="${esc(reply.author)}">${esc(reply.author)}</button><span>${esc(reply.time)}</span></div><div class="forum-response-to">↳ to <strong>${esc(parentName)}</strong></div><p>${esc(reply.text)}</p><button class="forum-inline-reply" type="button" aria-label="Reply to ${esc(reply.author)}" data-reply-to="${esc(reply.id)}" data-reply-name="${esc(reply.author)}">Reply ↗</button></div></article>`;
  const thread=entry+(depth<8?branch(reply.id,depth+1):'');
  return depth===0?`<section class="forum-response-group" aria-label="Conversation started by ${esc(reply.author)}">${thread}</section>`:thread
 }).join('')}
 let markup=branch('original',0);
 for(const reply of messages){if(!visited.has(reply.id))markup+=branch(reply.parentId,0)||branch(reply.id,0)}
 return markup
}
