function profileActivityItems(){
 const items=[];
 const stamp=id=>Number(String(id).match(/^(?:note|discussion|reply)-(\d+)$/)?.[1])||0;
 const date=(id,fallback)=>{const time=stamp(id);return time?new Date(time).toLocaleDateString('en-US',{month:'short',day:'numeric'}):fallback};
 for(const note of state.notes.filter(n=>isOwnAuthor(n.author)))items.push({kind:'note',label:'Shared a note',title:note.title,date:date(note.id,note.date||'Earlier'),order:stamp(note.id),id:note.id});
 for(const discussion of state.discussions.filter(d=>isOwnAuthor(d.author)))items.push({kind:'discussion',label:'Started a discussion',title:discussion.title,date:date(discussion.id,'Earlier'),order:stamp(discussion.id),id:discussion.id});
 for(const [discussionId,replies] of Object.entries(state.replies)){const discussion=state.discussions.find(d=>d.id===discussionId);if(!discussion||!Array.isArray(replies))continue;for(const reply of replies.filter(r=>isOwnAuthor(r.author)))items.push({kind:'reply',label:'Replied in a discussion',title:discussion.title,date:date(reply.id,'Earlier'),order:stamp(reply.id),id:discussionId})}
 return items.sort((a,b)=>b.order-a.order);
}
